import java.util.*;

class Solution {
  private int count;

  public int pathSum(TreeNode root, int targetSum) {
    Map<Long, Integer> prefixCounts = new HashMap<>();
    prefixCounts.put(0L, 1);
    walk(root, 0L, targetSum, prefixCounts);
    return count;
  }

  private void walk(TreeNode node, long sum, int target, Map<Long, Integer> prefixCounts) {
    if (node == null) return;
    sum += node.val;
    count += prefixCounts.getOrDefault(sum - target, 0);
    prefixCounts.merge(sum, 1, Integer::sum);
    walk(node.left, sum, target, prefixCounts);
    walk(node.right, sum, target, prefixCounts);
    prefixCounts.merge(sum, -1, Integer::sum);
  }
}
